package com.oms.order.service;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class OrderIntakeWorkspaceTest {
    static JdbcTemplate db;OrderIntakeWorkspace workspace;OrderCatalog catalog;ConfiguredPushReader sources;
    final Set<String> all=new LinkedHashSet<>(Arrays.asList("ORDER","REFUND","EXCHANGE"));
    @BeforeAll static void init(){String url=System.getenv("ORDER_TEST_URL");Assumptions.assumeTrue(url!=null&&url.contains("/order_workspace_test?"));db=OrderTestDatabase.jdbc(url);}
    @BeforeEach void seed(){for(String t:Arrays.asList("oms_order_pull_task","oms_refund_sync_item","oms_refund_sync","oms_exchange_sync_item","oms_exchange_sync","oms_order_pull_config","oms_refund_config","oms_exchange_config","oms_order_push_source"))db.update("DELETE FROM "+t);OrderRepository repo=new OrderRepository();ReflectionTestUtils.setField(repo,"jdbc",db);workspace=new OrderIntakeWorkspace();workspace.repository=repo;workspace.catalog=catalog=mock(OrderCatalog.class);workspace.sources=sources=mock(ConfiguredPushReader.class);when(catalog.channels("VERIFY")).thenReturn(Arrays.asList(map("channel_id",1,"channel_name","shop","channel_type","TM","enabled",1,"seller_nick","seller"),map("channel_id",2,"channel_name","other type","channel_type","OTHER","enabled",1)));when(catalog.channels("OTHER")).thenReturn(Collections.emptyList());when(sources.choices("VERIFY")).thenReturn(Collections.singletonList(map("key","source","label","source")));}
    @SuppressWarnings("unchecked") List<Map<String,Object>> rows(Map<String,Object> value){return (List<Map<String,Object>>)value.get("rows");}
    @Test void overviewReadsEachConfigInBatchesAndDoesNotProbePlatforms(){db.update("INSERT INTO oms_order_push_source(company_code,source_key,source_name,host,port,database_name,username,password_cipher,enabled) VALUES ('VERIFY','source','local','localhost',3306,'source','user','PRIVATE',1)");db.update("INSERT INTO oms_order_pull_config(company_code,channel_id,channel_name,source_key,seller_nick,initial_time,cursor_time) VALUES ('VERIFY',1,'shop','source','seller',NOW(),NOW())");db.update("INSERT INTO oms_refund_config(company_code,channel_id,source_key,seller_nick,initial_time,cursor_time,updated_by) VALUES ('VERIFY',1,'source','seller',NOW(),NOW(),'test')");Map<String,Object> row=rows(workspace.overview("VERIFY",all)).get(0);assertNotNull(row.get("order"));assertNotNull(row.get("refund"));assertNull(row.get("exchange"));assertEquals(1,rows(workspace.overview("VERIFY",Collections.singleton("REFUND"))).size());Map<String,Object> limited=rows(workspace.overview("VERIFY",Collections.singleton("REFUND"))).get(0);assertFalse(limited.containsKey("order"));assertFalse(limited.containsKey("exchange"));assertFalse(encode(row).contains("PRIVATE"));verify(catalog,times(3)).channels("VERIFY");verify(sources,times(3)).choices("VERIFY");verifyNoMoreInteractions(catalog,sources);}
    @Test void unconfiguredShopRemainsVisibleAndIsNotAConnectionFailure(){Map<String,Object> row=rows(workspace.overview("VERIFY",all)).get(0);assertEquals(1L,number(row,"channel_id"));assertNull(row.get("order"));assertNull(row.get("refund"));assertNull(row.get("exchange"));assertTrue(rows(workspace.overview("OTHER",all)).isEmpty());}
    void task(String kind,long id,String company,String state,String when){if(kind.equals("ORDER"))db.update("INSERT INTO oms_order_pull_task(id,company_code,channel_id,task_type,start_time,end_time,page_time,operator_name,status,create_time) VALUES (?,?,1,'MANUAL',NOW(),NOW(),NOW(),'test',?,?)",id,company,state,when);else db.update("INSERT INTO "+(kind.equals("REFUND")?"oms_refund_sync":"oms_exchange_sync")+"(id,company_code,channel_id,mode,start_time,end_time,"+(kind.equals("REFUND")?"page_time,":"")+"actor,state,request_key,create_time) VALUES (?,?,1,'MANUAL',NOW(),NOW(),"+(kind.equals("REFUND")?"NOW(),":"")+"'test',?,?,?)",id,company,state,kind+id,when);}
    @Test void sameNumberAcrossThreeKindsRemainsThreeDistinctTasks(){for(String t:all)task(t,101,"VERIFY",t.equals("ORDER")?"SUCCESS":"COMPLETED","2026-10-17 10:00:00");task("REFUND",102,"OTHER","FAILED","2026-10-17 11:00:00");Map<String,Object> result=workspace.tasks("VERIFY",all,Collections.emptyMap());assertEquals(3,number(result,"total"));Set<Object> ids=new HashSet<>();for(Map<String,Object> row:rows(result)){ids.add(row.get("task_key"));assertEquals("COMPLETED",row.get("state"));}assertEquals(3,ids.size());assertEquals(1,number(workspace.tasks("OTHER",all,Collections.emptyMap()),"total"));}
    @Test void taskPaginationIsStableWhenCreationTimesCollide(){for(String t:all)task(t,101,"VERIFY","PENDING","2026-10-17 10:00:00");Map<String,String> q=new HashMap<>();q.put("pageSize","1");Set<Object> seen=new HashSet<>();for(int page=1;page<=3;page++){q.put("pageNum",String.valueOf(page));List<Map<String,Object>> rows=rows(workspace.tasks("VERIFY",all,q));assertEquals(1,rows.size());seen.add(rows.get(0).get("task_key"));}assertEquals(3,seen.size());}
    @Test void taskPermissionsAndFiltersCannotSelectUnauthorizedTables(){for(String t:all)task(t,101,"VERIFY",t.equals("ORDER")?"SUCCESS":"COMPLETED","2026-10-17 10:00:00");Map<String,Object> r=workspace.tasks("VERIFY",Collections.singleton("REFUND"),Collections.emptyMap());assertEquals(1,number(r,"total"));assertEquals("REFUND",rows(r).get(0).get("kind"));assertThrows(IllegalArgumentException.class,()->workspace.tasks("VERIFY",Collections.singleton("REFUND"),Collections.singletonMap("kind","EXCHANGE")));assertEquals(1,number(workspace.tasks("VERIFY",all,new HashMap<String,String>(){{put("kind","ORDER");put("state","COMPLETED");}}),"total"));assertEquals(0,number(workspace.tasks("VERIFY",all,Collections.singletonMap("channelId","2")),"total"));assertEquals(0,number(workspace.tasks("VERIFY",Collections.emptySet(),Collections.emptyMap()),"total"));}
    @Test void invalidFiltersAndExpensivePageNumbersAreRejected(){for(Map<String,String> q:Arrays.asList(Collections.singletonMap("kind","' OR 1=1"),Collections.singletonMap("taskId","bad"),Collections.singletonMap("state","INVALID"),Collections.singletonMap("pageNum","100000")))assertThrows(IllegalArgumentException.class,()->workspace.tasks("VERIFY",all,q));}
}
